//! Channel vectors: a hand-built plan's Binder bytes and a proof made by the C++ ProverRounds and
//! read by the Rust VerifierRounds. Generated by `scripts/cpp_vectors/rounds_vectors.cpp`.

use std::collections::HashMap;
use std::rc::Rc;

use fp_core::chain::public::Binder;
use fp_core::chain::rounds::VerifierRounds;
use fp_core::chain::session::VerifierSession;
use fp_core::field::ext::E;
use fp_core::hash::calls::HashCalls;
use fp_core::hash::modes::Digest;
use fp_core::iop::message::Reader;
use fp_core::numbers::plan::{Cause, PlanRound, Planned};
use fp_core::numbers::setting::{RoundKind, Setting};

const VECTORS: &str = include_str!("../../fixtures/rounds_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn digest(s: &str) -> Digest {
    assert_eq!(s.len(), 64, "digest {}", s);
    let mut d = Digest::zero();
    for i in 0..8 {
        d.w[i] = u32::from_str_radix(&s[8 * i..8 * i + 8], 16).unwrap();
    }
    d
}

fn hex_bytes(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn f(s: &str) -> fp_core::field::ext::F {
    fp_core::field::ext::F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn kind(n: u32) -> RoundKind {
    match n {
        1 => RoundKind::Algebraic,
        2 => RoundKind::Epsilon,
        3 => RoundKind::Seed,
        4 => RoundKind::Positions,
        5 => RoundKind::Bits,
        6 => RoundKind::Seal,
        7 => RoundKind::Record,
        _ => RoundKind::Empty,
    }
}

fn plan(kv: &HashMap<&str, &str>, rounds: &[PlanRound]) -> Planned {
    let mut set = Setting::goldilocks();
    set.salt_bytes = kv["salt"].parse().unwrap();
    set.nonce_bytes = kv["nonce"].parse().unwrap();
    set.position_bytes = kv["position"].parse().unwrap();
    set.samples = kv["samples"].parse().unwrap();
    set.saved_coefficient = kv["saved"] == "1";
    set.target = kv["target"].parse().unwrap();
    Planned {
        set,
        rounds: rounds.to_vec(),
        messages: Vec::new(),
        parts: Vec::new(),
        cause: Cause::None,
        why_not: String::new(),
    }
}

fn binder(label: u64, plan: Rc<Planned>, config: &Digest) -> Binder {
    let mut b = Binder::new(label, plan);
    b.configuration(config);
    b.parameter("a", 42u64);
    b.statement("claim", 7u64);
    b
}

#[test]
fn rounds_vectors_match_the_cpp_reference() {
    let mut set_kv: Option<HashMap<&str, &str>> = None;
    let mut rounds: Vec<PlanRound> = Vec::new();
    let mut bind: Option<HashMap<&str, &str>> = None;
    let mut proof = Vec::new();
    let mut draws: HashMap<&str, String> = HashMap::new();

    for line in VECTORS.lines() {
        let first = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        if first == "SET" {
            set_kv = Some(kv);
        } else if first == "ROUND" {
            let mut r = PlanRound::default();
            r.name = kv["name"].to_string();
            r.kind = kind(kv["kind"].parse().unwrap());
            r.work_bits = kv["work"].parse().unwrap();
            r.message_bytes = kv["msg"].parse().unwrap();
            r.roots = kv["roots"].parse().unwrap();
            r.answers = kv["answers"].parse().unwrap();
            r.draw_e = kv["draw_e"].parse().unwrap();
            r.draw_nonzero = kv["nz"].parse().unwrap();
            r.draw_positions = kv["draw_pos"].parse().unwrap();
            r.log_n = kv["log_n"].parse().unwrap();
            r.draw_trits = kv["trits"].parse().unwrap();
            r.rows = kv["rows"].parse().unwrap();
            r.first_list = kv["first_list"].parse().unwrap();
            r.combinations = kv["combos"].parse().unwrap();
            r.sharing = kv["sharing"].parse().unwrap();
            rounds.push(r);
        } else if first == "BIND" {
            bind = Some(kv);
        } else if first == "PROOF" {
            proof = hex_bytes(line.split_whitespace().nth(1).unwrap());
        } else {
            let value = line.split_once(' ').map(|(_, v)| v.to_string()).unwrap_or_default();
            draws.insert(first, value);
        }
    }

    let p = Rc::new(plan(set_kv.as_ref().unwrap(), &rounds));
    let config = digest(bind.as_ref().unwrap()["config"]);

    // The Binder's two lists and their digest.
    {
        let mut b = binder(7, p.clone(), &config);
        let kv = bind.as_ref().unwrap();
        assert_eq!(b.parameter_bytes(), &hex_bytes(kv["pbytes"])[..], "parameter bytes");
        assert_eq!(b.statement_bytes(), &hex_bytes(kv["sbytes"])[..], "statement bytes");
        let mut calls = HashCalls::new();
        assert_eq!(b.parameters_digest(&mut calls), digest(kv["pdigest"]), "parameters digest");
    }

    // The proof through the port's channel.
    let mut b = binder(7, p.clone(), &config);
    let mut r = Reader::new(&proof);
    let mut session = VerifierSession::new();
    let mut calls = HashCalls::new();
    {
        let mut ch = VerifierRounds::new(&mut b, &mut r, &mut session, &mut calls);
        assert!(ch.ok());
        let mut x = E::default();
        assert!(ch.recv_e(&mut x));
        ch.close_empty("empty", &mut calls);

        assert!(ch.recv_e(&mut x));
        assert!(ch.recv_e(&mut x));
        {
            let (a, c) = {
                let mut d = ch.close_algebraic("alg", &mut calls);
                (d.draw_nonzero(&mut calls), d.draw_nonzero(&mut calls))
            };
            let want = draws["DRAW_ALG"].clone();
            let mut it = want.split_whitespace();
            assert_eq!(it.next().unwrap(), "i=0");
            assert_eq!(a, e(it.next().unwrap()));
            assert_eq!(it.next().unwrap(), "i=1");
            assert_eq!(c, e(it.next().unwrap()));
        }

        let seed = {
            let mut d = ch.close_seed("seed", &mut calls);
            d.seed(3, 2, &mut calls)
        };
        let want = draws["SEED"].clone();
        let ztxt = want.split_whitespace().next().unwrap().strip_prefix("z=").unwrap();
        let z: Vec<E> = ztxt.split(';').map(e).collect();
        assert_eq!(seed.z, z);
        let beta = want.split_whitespace().nth(1).unwrap().strip_prefix("beta=").unwrap();
        assert_eq!(seed.beta, e(beta));

        assert!(ch.recv_answer(&mut x));
        assert!(ch.recv_answer(&mut x));
        assert!(ch.recv_hiding_sum(&mut x));
        let eps = ch.close_epsilon("eps", &mut calls);
        assert_eq!(eps, e(draws["EPS"].trim()));

        assert!(ch.recv_e(&mut x));
        let t = {
            let mut d = ch.close_bits("bits", &mut calls);
            d.trits(70, &mut calls)
        };
        let want = draws["TRITS"].clone();
        let vt = want.split_once("v=").unwrap().1;
        let want_t: Vec<i8> = vt.split(',').map(|x| x.parse().unwrap()).collect();
        assert_eq!(t, want_t);

        assert!(ch.recv_e(&mut x));
        let (list, batch) = {
            let mut d = ch.close_positions("pos", &mut calls);
            let l = d.positions(4, &mut calls);
            let b = d.batching(&mut calls);
            (l, b)
        };
        let want = draws["POS"].clone();
        let dr = want.split_whitespace().nth(1).unwrap().strip_prefix("draws=").unwrap();
        let want_draws: Vec<u64> = dr.split(',').map(|x| x.parse().unwrap()).collect();
        assert_eq!(list.draws(), &want_draws[..]);
        let al = want.split_whitespace().nth(2).unwrap().strip_prefix("all=").unwrap();
        let want_all: Vec<u64> = al.split(',').map(|x| x.parse().unwrap()).collect();
        assert_eq!(list.all(), &want_all[..]);
        let bt = want.split_whitespace().nth(3).unwrap().strip_prefix("batch=").unwrap();
        assert_eq!(batch, e(bt));

        assert!(ch.recv_e(&mut x));
        ch.close_empty("last", &mut calls);

        let (ok, sealed) = ch.seal("seal", &mut calls);
        assert!(ok);
        let want = draws["SEAL_PROVER"].clone();
        let wd = want.split_whitespace().nth(1).unwrap().strip_prefix("digest=").unwrap();
        assert_eq!(sealed.digest(), &digest(wd));
        let run = want.split_whitespace().nth(2).unwrap().strip_prefix("run=").unwrap();
        assert_eq!(ch.run(), &digest(run));
        assert_eq!(ch.configuration(), &config);

        assert!(ch.finish());
    }
    assert!(session.accepted());

    // The C++ verifier saw the same values; the two sets in the fixture must agree.
    for (prover, verifier) in [
        ("DRAW_ALG", "VDRAW_ALG"),
        ("SEED", "VSEED"),
        ("EPS", "VEPS"),
        ("TRITS", "VTRITS"),
        ("POS", "VPOS"),
    ] {
        assert_eq!(draws[prover], draws[verifier], "{} and {}", prover, verifier);
    }
    assert_eq!(draws["SEAL_PROVER"].split_whitespace().nth(1), draws["SEAL_VERIFIER"].split_whitespace().nth(1));
    assert!(draws["VERIFIER"].contains("ok=1"));
    assert!(draws["VERIFIER"].contains("finish=1"));
    assert!(draws["VERIFIER"].contains("accepted=1"));
}

fn fixture() -> (Rc<Planned>, Digest, Vec<u8>) {
    let mut set_kv: Option<HashMap<&str, &str>> = None;
    let mut rounds: Vec<PlanRound> = Vec::new();
    let mut bind: Option<HashMap<&str, &str>> = None;
    let mut proof = Vec::new();
    for line in VECTORS.lines() {
        let first = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        if first == "SET" {
            set_kv = Some(kv);
        } else if first == "ROUND" {
            let mut r = PlanRound::default();
            r.name = kv["name"].to_string();
            r.kind = kind(kv["kind"].parse().unwrap());
            r.work_bits = kv["work"].parse().unwrap();
            r.message_bytes = kv["msg"].parse().unwrap();
            r.roots = kv["roots"].parse().unwrap();
            r.answers = kv["answers"].parse().unwrap();
            r.draw_e = kv["draw_e"].parse().unwrap();
            r.draw_nonzero = kv["nz"].parse().unwrap();
            r.draw_positions = kv["draw_pos"].parse().unwrap();
            r.log_n = kv["log_n"].parse().unwrap();
            r.draw_trits = kv["trits"].parse().unwrap();
            r.rows = kv["rows"].parse().unwrap();
            r.first_list = kv["first_list"].parse().unwrap();
            r.combinations = kv["combos"].parse().unwrap();
            r.sharing = kv["sharing"].parse().unwrap();
            rounds.push(r);
        } else if first == "BIND" {
            bind = Some(kv);
        } else if first == "PROOF" {
            proof = hex_bytes(line.split_whitespace().nth(1).unwrap());
        }
    }
    let p = Rc::new(plan(set_kv.as_ref().unwrap(), &rounds));
    let config = digest(bind.unwrap()["config"]);
    (p, config, proof)
}

fn consume(ch: &mut VerifierRounds<'_, '_, '_>, calls: &mut HashCalls) -> bool {
    let mut x = E::default();
    if !ch.recv_e(&mut x) {
        return false;
    }
    ch.close_empty("empty", calls);
    if !ch.recv_e(&mut x) || !ch.recv_e(&mut x) {
        return false;
    }
    {
        let mut d = ch.close_algebraic("alg", calls);
        d.draw_nonzero(calls);
        d.draw_nonzero(calls);
    }
    {
        let mut d = ch.close_seed("seed", calls);
        d.seed(3, 2, calls);
    }
    ch.recv_answer(&mut x);
    ch.recv_answer(&mut x);
    ch.recv_hiding_sum(&mut x);
    ch.close_epsilon("eps", calls);
    ch.recv_e(&mut x);
    {
        let mut d = ch.close_bits("bits", calls);
        d.trits(70, calls);
    }
    ch.recv_e(&mut x);
    {
        let mut d = ch.close_positions("pos", calls);
        d.positions(4, calls);
        d.batching(calls);
    }
    ch.recv_e(&mut x);
    ch.close_empty("last", calls);
    let (_, _) = ch.seal("seal", calls);
    ch.finish()
}

fn verdict(proof: &[u8]) -> (bool, bool) {
    let (p, config, _) = fixture();
    let mut b = binder(7, p, &config);
    let mut r = Reader::new(proof);
    let mut session = VerifierSession::new();
    let mut calls = HashCalls::new();
    let finish;
    {
        let mut ch = VerifierRounds::new(&mut b, &mut r, &mut session, &mut calls);
        finish = consume(&mut ch, &mut calls);
    }
    (finish, session.accepted())
}

#[test]
fn rounds_reject_cut_or_overlong_proofs() {
    let (_, _, proof) = fixture();
    assert_eq!(verdict(&proof), (true, true), "honest proof");

    let mut cut = proof.clone();
    cut.pop();
    assert_eq!(verdict(&cut), (false, false), "one byte missing");

    let mut short = proof.clone();
    short.truncate(proof.len() / 2);
    assert_eq!(verdict(&short), (false, false), "half a proof");

    let mut long = proof.clone();
    long.push(0);
    assert_eq!(verdict(&long), (false, false), "one byte left over");

    let empty: Vec<u8> = Vec::new();
    assert_eq!(verdict(&empty), (false, false), "no salt and no messages");
}
